/*!40000 ALTER TABLE `email_templates` DISABLE KEYS */;
INSERT INTO `email_templates` VALUES (1,'user_registered','Üye Kayıt','Hoş Geldiniz - {{site_name}}','<h2>Hoş Geldiniz, {{user_name}}!</h2><p>{{site_name}} ailesine katıldığınız için teşekkür ederiz.</p><p>Hesabınız başarıyla oluşturuldu. Hemen giriş yaparak hizmetlerimizi inceleyebilirsiniz.</p>','user_name,user_email,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(2,'password_reset','Şifre Sıfırlama','Şifre Sıfırlama - {{site_name}}','<h2>Şifre Sıfırlama</h2><p>Merhaba {{user_name}},</p><p>Şifrenizi sıfırlamak için aşağıdaki bağlantıya tıklayın:</p><p><a href=\"{{reset_link}}\">Şifremi Sıfırla</a></p><p>Bu bağlantı 1 saat geçerlidir.</p>','user_name,reset_link,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(3,'order_created','Sipariş Oluşturuldu','Siparişiniz Alındı #{{order_number}} - {{site_name}}','<h2>Siparişiniz Alındı</h2><p>Merhaba {{user_name}},</p><p>#{{order_number}} numaralı siparişiniz başarıyla oluşturuldu.</p><p>Toplam: {{total_amount}}</p><p>Ödeme yöntemi: {{payment_method}}</p>','user_name,order_number,total_amount,payment_method,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(4,'payment_received','Ödeme Alındı','Ödemeniz Alındı #{{order_number}} - {{site_name}}','<h2>Ödemeniz Alındı</h2><p>Merhaba {{user_name}},</p><p>#{{order_number}} numaralı siparişiniz için ödeme başarıyla alınmıştır.</p>','user_name,order_number,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(5,'order_completed','Sipariş Tamamlandı','Siparişiniz Tamamlandı #{{order_number}} - {{site_name}}','<h2>Siparişiniz Tamamlandı</h2><p>Merhaba {{user_name}},</p><p>#{{order_number}} numaralı siparişiniz başarıyla tamamlanmıştır.</p><p>Bizi tercih ettiğiniz için teşekkür ederiz.</p>','user_name,order_number,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(6,'order_cancelled','Sipariş İptal','Siparişiniz İptal Edildi #{{order_number}} - {{site_name}}','<h2>Sipariş İptal Edildi</h2><p>Merhaba {{user_name}},</p><p>#{{order_number}} numaralı siparişiniz iptal edilmiştir.</p>','user_name,order_number,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(7,'support_ticket_created','Destek Talebi Oluşturuldu','Destek Talebiniz Alındı #{{ticket_number}} - {{site_name}}','<h2>Destek Talebiniz Alındı</h2><p>Merhaba {{user_name}},</p><p>#{{ticket_number}} numaralı destek talebiniz oluşturuldu. En kısa sürede yanıt verilecektir.</p>','user_name,ticket_number,subject,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(8,'support_ticket_answered','Destek Talebi Yanıtlandı','Destek Talebiniz Yanıtlandı #{{ticket_number}} - {{site_name}}','<h2>Destek Talebiniz Yanıtlandı</h2><p>Merhaba {{user_name}},</p><p>#{{ticket_number}} numaralı destek talebinize yanıt verildi. Panelinizdencevabı görebilirsiniz.</p>','user_name,ticket_number,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(9,'admin_new_order','Yeni Sipariş (Admin)','Yeni Sipariş #{{order_number}}','<h2>Yeni Sipariş Geldi</h2><p>Sipariş No: #{{order_number}}</p><p>Müşteri: {{user_name}}</p><p>Toplam: {{total_amount}}</p>','user_name,order_number,total_amount,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(10,'bank_transfer_received','Havale Bildirimi Alındı','Havale Bildiriminiz Alındı - {{site_name}}','<h2>Havale Bildirimi</h2><p>Merhaba {{user_name}},</p><p>#{{order_number}} numaralı siparişiniz için havale bildiriminiz alınmıştır. En kısa sürede kontrol edilecektir.</p>','user_name,order_number,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(11,'payment_pending','Ödeme Bekliyor','Ödemeniz Bekleniyor #{{order_number}} - {{site_name}}','<h2>Ödeme Bekleniyor</h2><p>Merhaba {{user_name}},</p><p>#{{order_number}} numaralı siparişiniz için ödeme beklenmektedir.</p>','user_name,order_number,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(12,'order_processing','Sipariş İşlemde','Siparişiniz İşleme Alındı #{{order_number}} - {{site_name}}','<h2>Siparişiniz İşlemde</h2><p>Merhaba {{user_name}},</p><p>#{{order_number}} numaralı siparişiniz işleme alınmıştır.</p>','user_name,order_number,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(13,'waiting_customer_info','Eksik Bilgi','Eksik Bilgi - Sipariş #{{order_number}} - {{site_name}}','<h2>Eksik Bilgi Bekleniyor</h2><p>Merhaba {{user_name}},</p><p>#{{order_number}} numaralı siparişinizde eksik bilgi bulunmaktadır. Lütfen panelinizden eksik bilgileri tamamlayın.</p>','user_name,order_number,site_name','active','2026-06-30 23:57:17','2026-06-30 23:57:17');
