/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT INTO `faqs` VALUES (1,'Siparişim ne kadar sürede teslim edilir?','Teslim süresi seçtiğiniz pakete göre değişiklik göstermektedir. Her paketin detay sayfasında tahmini teslim süresi belirtilmiştir. Genellikle 1-10 iş günü arasında siparişler tamamlanmaktadır.',1,'active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(2,'Ödeme yöntemleri nelerdir?','Kredi kartı/banka kartı (PayTR/iyzico) ve Havale/EFT ile ödeme yapabilirsiniz. Tüm ödemeleriniz güvenli altyapılar üzerinden gerçekleştirilmektedir.',2,'active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(3,'Sipariş verdikten sonra nasıl takip edebilirim?','Üye girişi yaptıktan sonra \"Siparişlerim\" sayfasından tüm siparişlerinizi ve durumlarını takip edebilirsiniz.',3,'active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(4,'Destek talebi nasıl oluşturabilirim?','Üye panelinizden \"Destek\" bölümüne giderek yeni bir destek talebi oluşturabilirsiniz. Ekibimiz en kısa sürede yanıt verecektir.',4,'active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(5,'İade politikanız nedir?','Hizmet başlamadan önce tam iade yapılmaktadır. Hizmet başladıktan sonra iade koşulları, hizmetin durumuna göre değerlendirilmektedir. Detaylı bilgi için İade Politikası sayfamızı inceleyebilirsiniz.',5,'active','2026-06-30 23:57:17','2026-06-30 23:57:17'),(6,'Bilgilerim güvende mi?','Evet, tüm kişisel bilgileriniz KVKK kapsamında korunmaktadır. SSL sertifikası ile şifrelenmiş güvenli bağlantı kullanılmaktadır.',6,'active','2026-06-30 23:57:17','2026-06-30 23:57:17');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
