INSERT INTO `hero_slides` VALUES (1,'Sosyal medyada güçlü büyüme','Sosyal medya hizmetleriyle markanızı büyütün.','Instagram, TikTok, YouTube ve diğer platformlarda görünürlük, etkileşim ve hedef kitle büyümesi için profesyonel sosyal medya çözümleri.','Sosyal Medya Hizmetleri','/sosyal-medya-hizmetleri','heart','Sosyal Medya Hizmetleri','/sosyal-medya-hizmetleri','arrow-right','#ffffff','#14224a','Tüm Hizmetler','/kategoriler','grid','rgba(255,255,255,.12)','#ffffff','/assets/img/slider/social-media-v107.webp','/assets/img/slider/social-media-mobile-v107.webp','NetVera sosyal medya hizmetleri, içerik etkileşimi ve dijital büyüme çözümleri','#20104f','#a32078','rgba(24,10,65,.52)','#ffffff','#ff4fa3','Instagram, TikTok, YouTube ve daha fazlası','[{\"url\": \"/sosyal-medya-hizmetleri\", \"icon\": \"instagram\", \"color\": \"#f02d85\", \"label\": \"Instagram\"}, {\"url\": \"/sosyal-medya-hizmetleri\", \"icon\": \"tiktok\", \"color\": \"#111827\", \"label\": \"TikTok\"}, {\"url\": \"/sosyal-medya-hizmetleri\", \"icon\": \"youtube\", \"color\": \"#ff0033\", \"label\": \"YouTube\"}]',6500,10,'active',NULL,NULL,'2026-10-13 06:54:27','2026-10-13 06:54:27'),(2,'Ajans ve yazılım çözümleri','Hazır scriptlerden özel geliştirmeye güçlü altyapı.','Web sitesi, e-ticaret, mobil uygulama, hazır yazılım ve özel geliştirme ihtiyaçlarınız için ölçeklenebilir NetVera çözümlerini keşfedin.','Ajans & Yazılım','/ajans-yazilim-hizmetleri','layers','Ajans & Yazılımı İncele','/ajans-yazilim-hizmetleri','arrow-right','#ffffff','#14224a','Hazır Yazılımlar','/hazir-scriptler','code','rgba(255,255,255,.12)','#ffffff','/assets/img/slider/agency-software-v107.webp','/assets/img/slider/agency-software-mobile-v107.webp','NetVera ajans ve yazılım hizmetleri, web sitesi, uygulama ve özel yazılım geliştirme','#071b3e','#2140a8','rgba(5,17,54,.55)','#ffffff','#1fc7ff','Web, e-ticaret, mobil ve hazır yazılım','[{\"url\": \"/ajans-yazilim-hizmetleri\", \"icon\": \"globe\", \"color\": \"#2c7cff\", \"label\": \"Web Site\"}, {\"url\": \"/ajans-yazilim-hizmetleri\", \"icon\": \"store\", \"color\": \"#16a879\", \"label\": \"E-Ticaret\"}, {\"url\": \"/hazir-scriptler\", \"icon\": \"code\", \"color\": \"#7c5cff\", \"label\": \"Hazır Yazılım\"}]',7000,20,'active',NULL,NULL,'2026-10-13 06:54:27','2026-10-13 06:54:27'),(3,'Arama görünürlüğü ve ölçülebilir büyüme','SEO, GEO, AIO ve dijital pazarlama ile öne çıkın.','Arama motoru görünürlüğü, yapay zekâ odaklı içerik optimizasyonu, yerel keşfedilebilirlik ve performans reklamlarıyla markanızı ölçülebilir şekilde büyütün.','SEO & Dijital Pazarlama','/seo-dijital-pazarlama-hizmetleri','trending-up','SEO & Pazarlamayı İncele','/seo-dijital-pazarlama-hizmetleri','arrow-right','#ffffff','#14224a','Tüm Hizmetler','/kategoriler','grid','rgba(255,255,255,.12)','#ffffff','/assets/img/slider/seo-digital-marketing-v107.webp','/assets/img/slider/seo-digital-marketing-mobile-v107.webp','NetVera SEO, GEO, AIO, yerel arama ve dijital pazarlama analiz çözümleri','#10134f','#6d2ca5','rgba(7,16,58,.55)','#ffffff','#22d3ee','SEO, GEO, AIO, Ads ve yerel görünürlük','[{\"url\": \"/seo-dijital-pazarlama-hizmetleri\", \"icon\": \"search\", \"color\": \"#4f7cff\", \"label\": \"SEO\"}, {\"url\": \"/seo-dijital-pazarlama-hizmetleri\", \"icon\": \"map-pin\", \"color\": \"#22c7a8\", \"label\": \"Yerel Arama\"}, {\"url\": \"/seo-dijital-pazarlama-hizmetleri\", \"icon\": \"trending-up\", \"color\": \"#9b5cff\", \"label\": \"Dijital Reklam\"}]',6200,30,'active',NULL,NULL,'2026-10-13 06:54:27','2026-10-13 06:54:27');
