INSERT INTO `home_sections` VALUES (1,'hero','Dijitalde Güven Oluşturur, Markanızı Büyütürüz.','Gerçek kullanıcılar, kaliteli etkileşimler ve hızlı teslimat ile dijital dünyada güçlü bir itibar inşa edin.',NULL,'Hizmetleri İncele','/kategoriler',NULL,NULL,'arrow-right',1,'active','dijital hizmet',NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(2,'google_services','Google Hizmetleri','Google işletme profilinizi güçlendirin','Google haritalar yorumları, Google işletme puanı yükseltme, Google SEO destekli yorum hizmetleri ile işletmenizin dijital görünürlüğünü artırın. Gerçek kullanıcı etkileşimleri ile Google sıralamanızda fark yaratın.','Google Paketlerini İncele','/kategori/google-hizmetleri',NULL,NULL,'search',10,'active','google yorum hizmeti',NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(3,'instagram_services','Instagram Hizmetleri','Instagram hesabınızı büyütün','Instagram takipçi, beğeni, yorum ve etkileşim hizmetleri ile markanızı sosyal medyada öne çıkarın. Organik büyüme destekli, güvenilir ve hızlı teslimat.','Instagram Paketlerini İncele','/kategori/instagram-hizmetleri',NULL,NULL,'instagram',11,'active','instagram takipçi hizmeti',NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(4,'tiktok_services','TikTok Hizmetleri','TikTok içeriklerinizi öne çıkarın','TikTok takipçi, beğeni, izlenme ve paylaşım hizmetleri ile viral içerikler oluşturun. Hızlı teslimat ve kaliteli etkileşim garantisi.','TikTok Paketlerini İncele','/kategori/tiktok-hizmetleri',NULL,NULL,'zap',12,'active','tiktok hizmeti',NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(5,'youtube_services','YouTube Hizmetleri','YouTube kanalınızı büyütün','YouTube abone, izlenme, beğeni ve yorum hizmetleri ile kanalınızın performansını artırın. Gerçek kullanıcılar ile organik büyüme desteği.','YouTube Paketlerini İncele','/kategori/youtube-hizmetleri',NULL,NULL,'youtube',13,'active','youtube abone hizmeti',NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(6,'seo_services','SEO ve Dijital Reklam Hizmetleri','Arama motorlarında üst sıralara çıkın','Profesyonel SEO hizmetleri, Google Ads yönetimi ve dijital reklam çözümleri ile web sitenizin görünürlüğünü artırın. Hedef kitlenize doğrudan ulaşın.','SEO Paketlerini İncele','/kategori/seo-hizmetleri',NULL,NULL,'bar-chart',14,'active','SEO hizmeti',NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(7,'reputation','İtibar Yönetimi','Dijital itibarınızı profesyonelce yönetin','Olumsuz yorumların etkisini azaltın, olumlu müşteri deneyimlerini öne çıkarın. İşletmenizin online itibarını koruyun ve güçlendirin.','İtibar Yönetimi Paketleri','/kategoriler',NULL,NULL,'shield',15,'active','itibar yönetimi',NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(8,'how_it_works','Nasıl Çalışır?','4 basit adımda dijital hizmetinizi alın',NULL,NULL,NULL,NULL,NULL,'zap',20,'active',NULL,NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(9,'trust','Neden Bizi Tercih Etmelisiniz?','Binlerce müşterinin güvendiği profesyonel hizmet',NULL,NULL,NULL,NULL,NULL,'shield',30,'active',NULL,NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(10,'testimonials','Müşterilerimiz Ne Diyor?','Gerçek müşteri deneyimleri ve değerlendirmeler',NULL,NULL,NULL,NULL,NULL,'users',40,'active',NULL,'[\n    {\"name\":\"Ahmet K.\",\"role\":\"Restoran Sahibi\",\"text\":\"Google yorum hizmeti sayesinde işletmemizin puanı 4.9\'a yükseldi. Müşteri sayımız arttı!\",\"stars\":5},\n    {\"name\":\"Elif Y.\",\"role\":\"E-Ticaret Uzmanı\",\"text\":\"Instagram etkileşim paketleri gerçekten sonuç veriyor. Takipçi ve satışlarımız arttı.\",\"stars\":5},\n    {\"name\":\"Murat D.\",\"role\":\"Dijital Pazarlama Uzmanı\",\"text\":\"Hızlı teslimat ve kaliteli destek için teşekkürler. Gönül rahatlığıyla tavsiye ederim.\",\"stars\":5}\n]','2026-06-30 20:56:24','2026-06-30 20:56:24'),(11,'info_center','Bilgi Merkezi','Dijital hizmetler hakkında merak ettikleriniz',NULL,'Tüm Rehberleri Gör','/blog',NULL,NULL,'book-open',50,'active','dijital hizmet rehberi','[\n    {\"title\":\"Google yorum hizmeti nedir?\",\"desc\":\"Google haritalar ve işletme profilinize gerçek kullanıcı yorumları ekleyerek puanınızı yükseltin.\",\"link\":\"/blog\"},\n    {\"title\":\"Instagram etkileşimi nasıl artırılır?\",\"desc\":\"Takipçi, beğeni ve yorum hizmetleri ile Instagram hesabınızı büyütün.\",\"link\":\"/blog\"},\n    {\"title\":\"Sosyal medya etkileşimi neden önemlidir?\",\"desc\":\"Güçlü sosyal medya varlığı, marka bilinirliği ve müşteri güvenini artırır.\",\"link\":\"/blog\"},\n    {\"title\":\"İtibar yönetimi neden önemlidir?\",\"desc\":\"Online itibarınızı yöneterek müşteri güvenini koruyun ve satışlarınızı artırın.\",\"link\":\"/blog\"},\n    {\"title\":\"SEO ile dijital görünürlük nasıl artırılır?\",\"desc\":\"Arama motoru optimizasyonu ile web sitenizin organik trafiğini artırın.\",\"link\":\"/blog\"}\n]','2026-06-30 20:56:24','2026-06-30 20:56:24'),(12,'seo_text','Yorum Hizmeti - Türkiye\'nin Güvenilir Dijital Hizmet Platformu',NULL,'Yorum Hizmeti olarak Google, Instagram, TikTok, YouTube ve diğer dijital platformlarda markanızın görünürlüğünü artırıyoruz. Profesyonel ekibimiz, gerçek kullanıcı etkileşimleri ve hızlı teslimat ile işletmenizin dijital dünyada öne çıkmasını sağlıyor. Güvenli ödeme seçenekleri, 7/24 destek ve para iade garantisi ile hizmet veriyoruz. Türkiye genelinde binlerce işletme ve girişimciye dijital büyüme çözümleri sunuyoruz.',NULL,NULL,NULL,NULL,'info',90,'active','yorum hizmeti',NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24'),(13,'cta','Hemen Sipariş Verin, Farkı Hissedin!','Markanız için doğru adım atın, dijitalde bir adım öne geçin.',NULL,'Hizmetleri Keşfet','/kategoriler',NULL,NULL,'zap',95,'active',NULL,NULL,'2026-06-30 20:56:24','2026-06-30 20:56:24');
