DROP TABLE IF EXISTS `marketing_popups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `marketing_popups` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `internal_name` varchar(140) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('campaign','image','coupons') COLLATE utf8mb4_unicode_ci DEFAULT 'campaign',
  `orientation` enum('horizontal','vertical') COLLATE utf8mb4_unicode_ci DEFAULT 'horizontal',
  `eyebrow` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(220) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_alt` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primary_button_text` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primary_button_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primary_button_icon` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT 'arrow-right',
  `primary_button_bg` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#ffffff',
  `primary_button_text_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#17264e',
  `secondary_button_text` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secondary_button_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secondary_button_icon` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT 'grid',
  `secondary_button_bg` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#ffffff',
  `secondary_button_text_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#ffffff',
  `background_start` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#151a45',
  `background_end` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#6b4de8',
  `text_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#ffffff',
  `accent_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#d936a1',
  `coupon_items` json DEFAULT NULL,
  `open_delay_ms` int unsigned DEFAULT '1800',
  `reopen_hours` int unsigned DEFAULT '24',
  `auto_close_seconds` int unsigned DEFAULT '0',
  `closable` tinyint(1) DEFAULT '1',
  `close_on_backdrop` tinyint(1) DEFAULT '1',
  `once_per_session` tinyint(1) DEFAULT '0',
  `page_mode` enum('all','home','include','exclude') COLLATE utf8mb4_unicode_ci DEFAULT 'all',
  `path_rules` text COLLATE utf8mb4_unicode_ci,
  `sort_order` int DEFAULT '100',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci DEFAULT 'inactive',
  `starts_at` datetime DEFAULT NULL,
  `ends_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_popup_status_sort` (`status`,`sort_order`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
