INSERT INTO `nv_legacy_script_categories` VALUES (11,NULL,'sektorel-yonetim-yazilimlari','Sektörel Yönetim Yazılımları','Belirli sektörlerin işletme, saha ve içerik yönetimi ihtiyaçları için geliştirilen yazılımlar.','Sektörel Yönetim Yazılımları | NetVera','İşletmelerin sektöre özgü yönetim ihtiyaçları için geliştirilen NetVera yazılım çözümleri.',10,1),(12,NULL,'dijital-araclar-ve-otomasyon','Dijital Araçlar ve Otomasyon','İçerik, iletişim ve dijital iş süreçlerini destekleyen masaüstü ve otomasyon yazılımları.','Dijital Araçlar ve Otomasyon Yazılımları | NetVera','İçerik, iletişim ve dijital iş akışları için geliştirilen NetVera araçlarını inceleyin.',20,1),(13,12,'masaustu-bot-yazilimlar','Masaüstü Bot Yazılımlar','Netvera Masaüstü Bot Yazılımlar; işletme bulma, veri toplama, dijital pazarlama, müşteri keşfi ve tekrarlayan iş süreçlerini otomatikleştirmek için geliştirilen profesyonel masaüstü yazılımlarını bir araya getirir. Google Maps işletme bulucu, firma ve potansiyel müşteri keşfi, işletme verisi toplama ve farklı iş süreçlerine yönelik otomasyon araçları; ajansların, satış ekiplerinin ve işletmelerin manuel işlemlerini hızlandırmak amacıyla geliştirilmiştir.','Masaüstü Bot Yazılımlar ve Otomasyon Araçları | Netvera','Google Maps işletme bulucu, işletme veri toplama ve iş otomasyonu için geliştirilen Netvera masaüstü bot yazılımlarını inceleyin.',10,1);
