INSERT INTO `nv_legacy_script_images` VALUES (13,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-1.webp','NetVera Hafriyat yazılımı sık sorulan sorular ve müşteri bilgilendirme sayfası','Hizmetler, çalışma süreci ve firma hakkında sık sorulan soruların yönetilebilir biçimde yayınlandığı SSS sayfası.',70,1),(14,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-2.webp','NetVera Hafriyat yazılımı tamamlanan hafriyat işleri ve proje referansları sayfası','Tamamlanan hafriyat, kazı ve iş makinesi çalışmalarının görseller ve proje bilgileriyle sergilendiği projeler sayfası.',30,1),(15,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-3.webp','NetVera Hafriyat yazılımı kepçe ve iş makinelerinin listelendiği makine parkuru sayfası','Kepçe, ekskavatör ve diğer iş makinelerinin özellikleriyle birlikte sergilenebildiği yönetilebilir makine parkuru bölümü.',50,1),(16,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-4.webp','NetVera Hafriyat yazılımı iletişim formu, firma bilgileri ve konum alanlarının bulunduğu iletişim sayfası','Müşterilerin firmaya ulaşmasını ve hizmet talebi göndermesini kolaylaştıran iletişim ve teklif formu sayfası.',60,1),(17,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-5.webp','NetVera Hafriyat yazılımı hafriyat, kepçe kiralama ve iş makinesi hizmetleri sayfası','Hafriyat, kepçe kiralama, temel kazısı, altyapı ve diğer firma hizmetlerinin ayrı bölümler halinde sunulduğu hizmetler sayfası.',40,1),(18,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-6.webp','NetVera Hafriyat yazılımı kurumsal firma tanıtımı ve hakkımızda sayfası','Firmanın deneyimi, çalışma yaklaşımı, kurumsal bilgileri ve güven unsurlarının ziyaretçilere aktarıldığı hakkımızda sayfası.',20,1),(19,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-7.webp','NetVera Hafriyat yazılımı saha çalışmaları ve iş makinesi fotoğraflarının yer aldığı galeri sayfası','Firmanın saha çalışmalarını, iş makinelerini ve tamamlanan işlerden gerçek görselleri sergileyebildiği galeri bölümü.',90,1),(20,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-8.webp','NetVera Hafriyat yazılımı sektörel blog yazılarının listelendiği blog sayfası','Hafriyat, iş makineleri ve firma hizmetleriyle ilgili bilgilendirici içeriklerin yayınlanabildiği yönetilebilir blog sayfası.',80,1),(21,11,'/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-ekran-goruntusu-9.webp','NetVera Hafriyat yazılımı ana sayfa, hizmetler, projeler ve iş makineleri web sitesi arayüzü','Hizmetler, makine parkuru, projeler, kurumsal bilgiler ve iletişim alanlarını tek yapıda sunan NetVera Hafriyat ana sayfa görünümü.',10,1),(22,12,'/uploads/scripts/bobinajci-sitesi-yazilimi/bobinajci-sitesi-yazilimi-ekran-goruntusu-1.webp','Netvera Bobinajcı Sitesi Yazılımı motor bobinaj, elektrik motoru, pompa ve teknik servis hizmetleri sayfası','AC/DC motor bobinaj, elektrik motoru sarımı, pompa tamiri, jeneratör bakımı, sanayi motoru bakımı ve yerinde servis hizmetlerinin sunulduğu hizmetler sayfası.',20,1),(23,12,'/uploads/scripts/bobinajci-sitesi-yazilimi/bobinajci-sitesi-yazilimi-ekran-goruntusu-2.webp','Netvera Bobinajcı Sitesi Yazılımı motor bobinaj, motor bakımı ve elektrik motoru blog içerikleri sayfası','Motor arızaları, motor bakımı, enerji verimliliği, elektrik motoru bobinajı, dalgıç pompa ve jeneratör bakımı hakkında sektörel içeriklerin yayınlandığı blog sayfası.',40,1),(24,12,'/uploads/scripts/bobinajci-sitesi-yazilimi/bobinajci-sitesi-yazilimi-ekran-goruntusu-3.webp','Netvera Bobinajcı Sitesi Yazılımı motor bobinaj, elektrik motoru hizmetleri ve kurumsal ana sayfa görünümü','Motor bobinaj, elektrik motoru sarımı, teknik servis, referanslar, blog, teklif ve iletişim bölümlerini bir araya getiren Netvera Bobinajcı Sitesi Yazılımı ana sayfa görünümü.',10,1),(25,12,'/uploads/scripts/bobinajci-sitesi-yazilimi/bobinajci-sitesi-yazilimi-ekran-goruntusu-4.webp','Netvera Bobinajcı Sitesi Yazılımı bobinaj firması referansları ve müşteri yorumları sayfası','Motor bobinaj ve elektromekanik hizmet alan işletmelerin referanslarının ve müşteri deneyimlerinin sergilenebildiği Netvera Bobinajcı Sitesi Yazılımı referans sayfası.',50,1),(26,12,'/uploads/scripts/bobinajci-sitesi-yazilimi/bobinajci-sitesi-yazilimi-ekran-goruntusu-5.webp','Netvera Bobinajcı Sitesi Yazılımı bobinaj firması kurumsal hakkımızda ve motor bakım çözümleri sayfası','Bobinaj firmasının deneyimini, misyonunu, vizyonunu, kalite yaklaşımını ve motor bobinaj hizmet sürecini ziyaretçilere tanıtabildiği kurumsal hakkımızda sayfası.',30,1),(27,12,'/uploads/scripts/bobinajci-sitesi-yazilimi/bobinajci-sitesi-yazilimi-ekran-goruntusu-6.webp','Netvera Bobinajcı Sitesi Yazılımı motor bobinaj iletişim, servis talebi ve teklif formu sayfası','Müşterilerin motor bobinaj ve elektrik motoru servis taleplerini iletebildiği; telefon, WhatsApp, e-posta, adres ve teklif formu alanlarının bulunduğu iletişim sayfası.',60,1),(28,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-1.webp','Netvera WhatsApp toplu mesaj sistemi üzerinden metin ve görsel bloklarının WhatsApp Web ile gönderimi','Hazırlanan kampanya metinlerinin ve görsellerinin WhatsApp Web oturumu üzerinden sıralı biçimde gönderilmesini gösteren gerçek çalışma ekranı.',10,1),(29,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-2.webp','WhatsApp toplu mesaj programı kampanya yönetimi, gönderim kuyruğu ve mesaj şablonları ekranı','WhatsApp Web bağlantısı üzerinden izinli alıcı listeleri için mesaj ve görsel bloklarıyla kampanyaların oluşturulduğu, gönderim ve sonuçların takip edildiği ekran.',20,1),(30,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-3.webp','WhatsApp toplu mesaj kampanyası oluşturma, alıcı listesi seçme ve canlı mesaj önizleme ekranı','Alıcı listesi, WhatsApp blok şablonu, gönderim aralığı ve günlük limit seçilerek yeni mesaj kampanyasının oluşturulduğu canlı önizlemeli çalışma ekranı.',30,1),(31,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-4.webp','WhatsApp toplu mesaj gönderim kuyruğunda firma, telefon, blok ilerlemesi ve gönderim durumu takibi','WhatsApp kampanyalarında her işletmenin mesaj bloklarının ilerlemesi, planlanan zaman, son gönderim ve hata durumlarının takip edildiği gönderim kuyruğu ekranı.',40,1),(32,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-5.webp','WhatsApp toplu mesaj kampanyaları için sıralı metin ve görsel blok şablonları oluşturma ekranı','Metin ve görsellerin istenilen sırada bloklar halinde hazırlanarak WhatsApp kampanyalarında yeniden kullanılabildiği mesaj şablonu yönetim ekranı.',50,1),(33,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-6.webp','Toplu mail kampanyalarının gönderilen, başarısız, bekleyen ve istenmeyen sonuçlarını gösteren raporlama ekranı','Toplam alıcı, başarılı ve başarısız gönderimler, kuyrukta bekleyen kayıtlar ve ayrıntılı gönderim günlüklerinin Excel veya CSV olarak dışa aktarılabildiği raporlama ekranı.',60,1),(34,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-7.webp','Toplu mail programı ile alıcı listesi, SMTP hesabı, şablon ve gönderim aralığı yönetilen e-posta kampanyaları','Alıcı listesi, gönderen SMTP hesabı, e-posta şablonu ve gönderim aralığı seçilerek toplu e-posta kampanyalarının oluşturulduğu ve takip edildiği ekran.',70,1),(35,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-8.webp','Toplu mail gönderim kuyruğu, planlanan gönderim zamanı ve e-posta gönderim durumları ekranı','Planlanan, gönderilen ve bekleyen e-postaların firma, gönderim saati, deneme sayısı ve hata durumlarıyla canlı olarak takip edildiği gönderim kuyruğu.',80,1),(36,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-9.webp','Toplu e-posta gönderimleri için firma bilgileriyle kişiselleştirilebilen dinamik e-posta şablonu hazırlama ekranı','Firma adı, yetkili, e-posta, telefon, web sitesi, şehir ve kategori gibi dinamik değişkenlerin kullanıldığı kişiselleştirilmiş e-posta şablonlarının hazırlandığı ekran.',90,1),(37,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-10.webp','Toplu e-posta gönderimi için SMTP hesap ekleme, bağlantı testi ve gönderen hesabı yönetimi ekranı','Birden fazla SMTP gönderen profilinin tanımlanabildiği, bağlantının test edilebildiği ve toplu e-posta kampanyalarında kullanılacak hesapların yönetildiği ekran.',100,1),(38,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-11.webp','Müşteriye özel PDF teklif ve kurumsal sunum şablonu oluşturma ve canlı önizleme ekranı','Firma ve alıcı bilgilerine göre otomatik kişiselleştirilebilen teklif, tanıtım, rapor ve kurumsal sunum PDF\'lerinin tasarlandığı canlı önizlemeli PDF şablon ekranı.',110,1),(39,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-12.webp','Instagram toplu DM programı ile işletme profillerine mesaj ve görsel kampanyaları oluşturma ekranı','Alıcı listelerinde bulunan Instagram profilleri için sıralı mesaj ve görsel bloklarından oluşan DM kampanyalarının oluşturulduğu Instagram otomasyon ekranı.',120,1),(40,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-13.webp','Netvera Instagram toplu DM gönderme programı ile işletme hesabına mesaj ve görsel gönderimi','Hazırlanan Instagram kampanyasının gerçek Instagram oturumu üzerinden hedef işletme profiline metin ve görsellerle iletilmesini gösteren çalışma ekranı.',130,1),(41,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-14.webp','Instagram toplu DM gönderimleri için dinamik metin ve görsel bloklarından oluşan mesaj şablonları','Instagram DM kampanyalarında kullanılmak üzere kişiselleştirilebilir metinlerin ve görsellerin sıralı bloklar halinde hazırlandığı mesaj şablonu ekranı.',140,1),(42,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-15.webp','Google Maps veri çekme botu gönderim limitleri, çalışma saatleri, Google Places ve medya klasörü ayarları','Gönderim aralıkları, günlük limitler, çalışma saatleri, işletme bulma seçenekleri, Google Places bağlantısı ve PDF medya klasörü gibi sistem tercihlerinin yönetildiği ayarlar ekranı.',150,1),(43,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-16.webp','Google Maps veri çekme botu, toplu mail, WhatsApp, Instagram ve işletme bulma özellikli Netvera masaüstü yazılımı','Google Maps işletme verisi toplama, firma bulma, toplu e-posta, WhatsApp mesajları, Instagram iletişimi, PDF ve otomasyon özelliklerini bir araya getiren Netvera masaüstü bot yazılımı.',160,1),(44,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-17.webp','Google Maps işletme verisi çekme ve sektör ile konuma göre firma bulma ekranı','Anahtar kelime ve sektör seçerek Google Maps üzerinde işletme araştırması yapılan, firmaların harita sonuçlarından toplanabildiği işletme bulma ekranı.',170,1),(45,43,'/uploads/scripts/google-maps-veri-cekme-isletme-bulucu-botu/google-maps-veri-cekme-isletme-bulucu-botu-ekran-goruntusu-18.webp','Firma listesi oluşturma, işletme iletişim bilgilerini tarama ve Instagram verilerini toplama ekranı','Google Maps ve web sitesi araştırmalarından elde edilen işletmelerin firma adı, e-posta, telefon, WhatsApp, web sitesi, şehir, kategori ve Instagram bilgileriyle yönetildiği alıcı listesi ekranı.',180,1),(46,48,'/uploads/scripts/netvera-nakliye-script-yazilimi-pro/netvera-nakliye-script-yazilimi-pro-ekran-goruntusu-1.webp','NetVera Nakliye Script Yazılımı Pro ana sayfa tasarımı, lojistik hizmetleri, filo, sektörler ve teklif alma bölümleri','Nakliye ve lojistik firmaları için hazırlanan mobil uyumlu kurumsal ana sayfa; hizmetler, filo, sektörler, global ağ, müşteri yorumları ve teklif alma alanlarını tek yapıda sunar.',10,1),(47,48,'/uploads/scripts/netvera-nakliye-script-yazilimi-pro/netvera-nakliye-script-yazilimi-pro-ekran-goruntusu-2.webp','Nakliye scripti blog ve lojistik rehberi sayfasında lojistik haberleri, rehber içerikleri, kategori ve etiket yapısı','Nakliye ve lojistik sektörüne yönelik rehberler, sektörel haberler ve uzmanlık içeriklerinin kategori ve etiketlerle yayınlanabildiği SEO odaklı blog sistemi.',20,1),(48,48,'/uploads/scripts/netvera-nakliye-script-yazilimi-pro/netvera-nakliye-script-yazilimi-pro-ekran-goruntusu-3.webp','Nakliye web sitesi filo yönetimi sayfasında treyler, frigorifik araç, panelvan ve ağır nakliye araçları','Nakliye firmasının araç filosunu araç tipi, kapasite, görsel ve açıklamalarla ziyaretçilere sunabildiği dinamik filo yönetim modülü.',30,1),(49,48,'/uploads/scripts/netvera-nakliye-script-yazilimi-pro/netvera-nakliye-script-yazilimi-pro-ekran-goruntusu-4.webp','NetVera lojistik web sitesi global lojistik ağı, uluslararası taşıma bölgeleri ve stratejik lojistik koridorları','Uluslararası taşıma ağı, hizmet verilen ülkeler, lojistik koridorlar ve bölgesel operasyon bilgilerini görsel olarak sunan global ağ sayfası.',40,1),(50,48,'/uploads/scripts/netvera-nakliye-script-yazilimi-pro/netvera-nakliye-script-yazilimi-pro-ekran-goruntusu-5.webp','NetVera nakliye ve lojistik web sitesi Hakkımızda sayfası ile kurumsal firma tanıtım ve iletişim alanı','Nakliye ve lojistik firmasının kurumsal kimliğini, operasyon yaklaşımını, iletişim bilgilerini ve güven mesajlarını ziyaretçilere aktaran yönetilebilir Hakkımızda sayfası.',50,1),(51,48,'/uploads/scripts/netvera-nakliye-script-yazilimi-pro/netvera-nakliye-script-yazilimi-pro-ekran-goruntusu-6.webp','Nakliye scripti hizmetler sayfasında karayolu, denizyolu, havayolu ve demiryolu taşımacılığı hizmetleri','Karayolu, denizyolu, havayolu ve demiryolu taşımacılığı gibi lojistik hizmetlerin ayrı kartlar ve detay sayfalarıyla sunulduğu hizmetler bölümü.',60,1),(52,48,'/uploads/scripts/netvera-nakliye-script-yazilimi-pro/netvera-nakliye-script-yazilimi-pro-ekran-goruntusu-7.webp','NetVera nakliye web sitesi iletişim sayfasında mesaj formu, firma iletişim bilgileri, harita ve teklif alma alanı','Firma iletişim bilgileri, mesaj formu, çalışma saatleri, harita, WhatsApp desteği ve teklif alma yönlendirmesini bir araya getiren kurumsal iletişim sayfası.',70,1),(53,48,'/uploads/scripts/netvera-nakliye-script-yazilimi-pro/netvera-nakliye-script-yazilimi-pro-ekran-goruntusu-8.webp','NetVera Nakliye Scripti sektörel lojistik çözümler sayfasında otomotiv, sağlık, perakende ve tarım lojistiği','Otomotiv, sağlık ve ilaç, perakende, tarım ve gıda gibi farklı sektörlere sunulan lojistik hizmetlerin ayrı içeriklerle tanıtılabildiği sektör yönetimi.',80,1);
/*!40000 ALTER TABLE `nv_legacy_script_images` ENABLE KEYS */;
DROP TABLE IF EXISTS `nv_legacy_script_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `nv_legacy_script_products` (
  `legacy_id` int unsigned NOT NULL AUTO_INCREMENT,
  `category_legacy_id` int unsigned NOT NULL,
  `slug` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `short_desc` text COLLATE utf8mb4_unicode_ci,
  `description` longtext COLLATE utf8mb4_unicode_ci,
  `cover_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` decimal(12,2) NOT NULL DEFAULT '0.00',
  `old_price` decimal(12,2) DEFAULT NULL,
  `badge` varchar(70) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` text COLLATE utf8mb4_unicode_ci,
  `focus_keyword` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `public_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`legacy_id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_cat` (`category_legacy_id`),
  KEY `idx_public` (`active`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
