INSERT INTO `nv_legacy_script_products` VALUES (11,11,'hafriyat-yazilimi','NetVera Hafriyat Sitesi Yazılımı','Hafriyat, nakliye ve iş makinesi işletmeleri için geliştirilen yönetim panelli, mobil uyumlu ve sektörel web yazılımı.','NetVera Hafriyat Yazılımı; hafriyat, nakliye, kazı, dolgu, yıkım ve iş makinesi hizmeti sunan işletmelerin dijital süreçlerini yönetebilmesi için geliştirilmiş sektörel bir yazılımdır.\r\n\r\nYönetim paneli sayesinde işletmenin hizmetleri, araç ve iş makinesi bilgileri, projeleri, galeri içerikleri ve kurumsal sayfaları tek merkezden yönetilebilir.\r\n\r\nSistem, standart bir tanıtım sitesinden farklı olarak hafriyat ve nakliye sektörünün ihtiyaçlarına göre hazırlanmış yönetilebilir bir altyapı sunar. Mobil uyumlu arayüzü sayesinde ziyaretçiler telefon, tablet ve masaüstü cihazlardan hizmetlere kolayca ulaşabilir.\r\n\r\nSEO uyumlu sayfa yapısı; hafriyat hizmetleri, nakliye hizmetleri, iş makinesi hizmetleri ve işletmenin faaliyet alanlarıyla ilgili içeriklerin arama motorları tarafından daha açık biçimde anlaşılmasını destekler.','/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-kapak-20260814143959-9b5c.webp',10000.00,13000.00,'Satışa Hazır','Hafriyat Yazılımı ve Nakliye Yönetim Sistemi | NetVera','Hafriyat, nakliye ve iş makinesi firmaları için geliştirilen NetVera Hafriyat Yazılımı ile hizmet, araç, proje ve kurumsal içeriklerinizi tek panelden yönetin.','hafriyat yazılımı','{\"id\":\"11\",\"category_id\":\"11\",\"name\":\"NetVera Hafriyat Sitesi Yazılımı\",\"slug\":\"hafriyat-yazilimi\",\"short_desc\":\"Hafriyat, nakliye ve iş makinesi işletmeleri için geliştirilen yönetim panelli, mobil uyumlu ve sektörel web yazılımı.\",\"description\":\"NetVera Hafriyat Yazılımı; hafriyat, nakliye, kazı, dolgu, yıkım ve iş makinesi hizmeti sunan işletmelerin dijital süreçlerini yönetebilmesi için geliştirilmiş sektörel bir yazılımdır.\\r\\n\\r\\nYönetim paneli sayesinde işletmenin hizmetleri, araç ve iş makinesi bilgileri, projeleri, galeri içerikleri ve kurumsal sayfaları tek merkezden yönetilebilir.\\r\\n\\r\\nSistem, standart bir tanıtım sitesinden farklı olarak hafriyat ve nakliye sektörünün ihtiyaçlarına göre hazırlanmış yönetilebilir bir altyapı sunar. Mobil uyumlu arayüzü sayesinde ziyaretçiler telefon, tablet ve masaüstü cihazlardan hizmetlere kolayca ulaşabilir.\\r\\n\\r\\nSEO uyumlu sayfa yapısı; hafriyat hizmetleri, nakliye hizmetleri, iş makinesi hizmetleri ve işletmenin faaliyet alanlarıyla ilgili içeriklerin arama motorları tarafından daha açık biçimde anlaşılmasını destekler.\",\"price\":\"10000.00\",\"old_price\":\"13000.00\",\"badge\":\"Satışa Hazır\",\"tags\":\"hafriyat yönetim yazılımı, nakliye yazılımı, hafriyat web yazılımı, iş makinesi yönetim sistemi, hafriyat firma yazılımı\",\"icon\":\"truck\",\"tone\":\"teal\",\"buy_url\":null,\"demo_url\":\"https://demokepce.netvera.tr\",\"demo_video_url\":null,\"demo_is_active\":\"1\",\"demo_is_public\":\"1\",\"demo_display_mode\":\"public\",\"image\":\"/uploads/scripts/hafriyat-yazilimi/hafriyat-yazilimi-kapak-20260814143959-9b5c.webp\",\"modules_json\":\"[\\\"Yönetim paneli\\\", \\\"Hizmet yönetimi\\\", \\\"Araç ve iş makinesi yönetimi\\\", \\\"Proje yönetimi\\\", \\\"Galeri\\\", \\\"Kurumsal içerikler\\\", \\\"İletişim ve talep alanları\\\", \\\"Mobil uyum\\\", \\\"SEO altyapısı\\\", \\\"PHP/MySQL\\\", \\\"cPanel uyumluluğu\\\"]\",\"specs_json\":\"[]\",\"license_json\":\"[]\",\"install_info\":\"\",\"current_version\":\"1.0.0\",\"last_updated_on\":\"2026-08-14\",\"update_duration_type\":\"lifetime\",\"update_duration_months\":null,\"support_duration_type\":\"months\",\"support_duration_months\":\"1\",\"install_type\":\"web\",\"faq_json\":\"[]\",\"is_featured\":\"1\",\"is_popular\":\"0\",\"is_new\":\"0\",\"sort_order\":\"10\",\"is_active\":\"1\",\"meta_title\":\"Hafriyat Yazılımı ve Nakliye Yönetim Sistemi | NetVera\",\"meta_description\":\"Hafriyat, nakliye ve iş makinesi firmaları için geliştirilen NetVera Hafriyat Yazılımı ile hizmet, araç, proje ve kurumsal içeriklerinizi tek panelden yönetin.\",\"focus_keyword\":\"hafriyat yazılımı\",\"secondary_keywords\":\"hafriyat web yazılımı, kepçe kiralama yazılımı, iş makinesi web sitesi, hafriyat yönetim paneli, hafriyat firma sitesi, sektörel web yazılımı,kepce scripti, hafriyat scripti\",\"showcase_enabled\":\"0\",\"showcase_slug\":null,\"showcase_button_label\":\"Özellikleri Detaylı İncele\"}',10,1),(12,11,'bobinajci-sitesi-yazilimi','Netvera Bobinajcı Sitesi Yazılımı','Netvera Bobinajcı Sitesi Yazılımı; motor bobinaj, elektrik motoru sarımı, bakım-onarım ve elektromekanik servis firmaları için geliştirilen, yönetim panelli, mobil uyumlu ve SEO odaklı profesyonel sektörel web yazılımıdır.','Netvera Bobinajcı Sitesi Yazılımı, Türkiye genelinde faaliyet gösteren bobinaj firmaları, elektrik motoru servisleri, motor sarım atölyeleri ve elektromekanik işletmeleri için özel olarak geliştirilmiş profesyonel bir sektörel web sitesi yazılımıdır. Bobinajcı sitesi ihtiyacı olan işletmelerin hizmetlerini, yaptığı çalışmaları, referanslarını ve kurumsal kimliğini internet ortamında profesyonel biçimde sunabilmesi için hazırlanmıştır.\r\n\r\nNetvera Bobinajcı Sitesi Yazılımı standart kurumsal web sitesi şablonlarından farklı olarak doğrudan motor bobinaj ve elektrik motoru bakım-onarım sektörünün ihtiyaçlarına göre yapılandırılmıştır. AC/DC motor bobinaj, elektrik motoru sarımı, motor bakım ve onarım, arıza tespiti, pompa servisi, redüktör servisi, jeneratör bakımı, blower servisi ve yerinde teknik servis gibi çalışmalar ayrı hizmet içerikleriyle ziyaretçilere sunulabilir.\r\n\r\nYönetim paneli sayesinde hizmetler, galeri görselleri, referanslar, müşteri yorumları, kurumsal içerikler, blog yazıları, iletişim bilgileri ve çeşitli site ayarları merkezi olarak yönetilebilir. İşletme sahibi yeni bir motor bobinaj hizmeti eklemek, yapılan çalışmaların fotoğraflarını değiştirmek veya kurumsal bilgilerini güncellemek için site kodlarına müdahale etmek zorunda kalmaz.\r\n\r\nBobinaj sektöründe hizmet arayan müşteriler yalnızca firma adını değil, işletmenin yaptığı işleri, teknik uzmanlığını ve daha önce tamamladığı çalışmaları da görmek ister. Netvera Bobinajcı Sitesi Yazılımı içerisinde bulunan galeri, referans, hizmet detayları ve kurumsal içerik bölümleri sayesinde motor sarımı, stator bobinajı, elektrik motoru bakımı, rulman değişimi, pompa servisi, redüktör bakımı ve diğer elektromekanik çalışmalar profesyonel biçimde sergilenebilir.\r\n\r\nYazılım SEO odaklı içerik yapısına sahiptir. Bobinajcı sitesi, bobinaj web sitesi, motor bobinaj web sitesi, elektrik motoru servis sitesi, motor sarım sitesi ve elektromekanik web sitesi gibi sektörel arama niyetlerine uygun sayfalar ve içerikler oluşturulabilir. Elektrik motoru sarımı, AC motor bobinajı, DC motor bobinajı, pompa servisi ve redüktör bakım hizmetleri gibi farklı hizmetlerin ayrı içeriklerle sunulabilmesi, işletmenin sunduğu hizmetlerin arama motorları tarafından daha açık biçimde anlaşılmasına yardımcı olur.\r\n\r\nBlog yönetimi sayesinde motor bobinaj nedir, elektrik motoru neden yanar, motor sarımı nasıl yapılır, elektrik motoru bakımı, rulman arızaları, redüktör bakımı, pompa arızaları ve endüstriyel motor servisleri gibi sektörel konularda özgün içerikler yayınlanabilir. Böylece web sitesi yalnızca firma tanıtımı yapan bir yapı olmaktan çıkarak bobinaj ve elektromekanik sektöründe bilgi sunan kapsamlı bir kurumsal site haline getirilebilir.\r\n\r\nNetvera Bobinajcı Sitesi Yazılımı telefon, tablet ve masaüstü cihazlarla uyumlu responsive tasarıma sahiptir. Türkiye genelindeki bobinaj atölyeleri, motor sarım işletmeleri, elektrik motoru bakım servisleri, elektromekanik firmaları, pompa servisleri ve redüktör bakım işletmeleri sistemi kendi marka, hizmet ve iletişim bilgileriyle kullanabilir.\r\n\r\nHer kurulumda müşteri kendi yönetici kullanıcı adını ve şifresini oluşturur. Paket içerisinde tüm müşteriler tarafından kullanılan ortak veya varsayılan bir yönetici şifresi bulunmaz. Yazılım cPanel tabanlı uygun Linux hosting ortamlarında kurulabilecek production paketiyle teslim edilir.\r\n\r\nNetvera Bobinajcı Sitesi Yazılımı yalnızca hazır bir web tasarım şablonu değil; bobinaj ve elektromekanik sektöründeki işletmelerin dijital kurumsal kimliğini güçlendirmek, hizmetlerini daha anlaşılır sunmak, yapılan çalışmaları sergilemek ve internette sürdürülebilir bir kurumsal görünürlük altyapısı oluşturmak amacıyla geliştirilmiş sektörel web yazılımıdır.','/uploads/scripts/bobinajci-sitesi-yazilimi/bobinajci-sitesi-yazilimi-kapak.webp',4000.00,7000.00,'Satışa Hazır','Bobinajcı Sitesi Yazılımı | Netvera','Bobinajcı sitesi arayan motor bobinaj ve elektrik motoru servisleri için yönetim panelli, mobil uyumlu Netvera web yazılımını inceleyin.','bobinajcı sitesi','{\"id\":\"12\",\"category_id\":\"11\",\"name\":\"Netvera Bobinajcı Sitesi Yazılımı\",\"slug\":\"bobinajci-sitesi-yazilimi\",\"short_desc\":\"Netvera Bobinajcı Sitesi Yazılımı; motor bobinaj, elektrik motoru sarımı, bakım-onarım ve elektromekanik servis firmaları için geliştirilen, yönetim panelli, mobil uyumlu ve SEO odaklı profesyonel sektörel web yazılımıdır.\",\"description\":\"Netvera Bobinajcı Sitesi Yazılımı, Türkiye genelinde faaliyet gösteren bobinaj firmaları, elektrik motoru servisleri, motor sarım atölyeleri ve elektromekanik işletmeleri için özel olarak geliştirilmiş profesyonel bir sektörel web sitesi yazılımıdır. Bobinajcı sitesi ihtiyacı olan işletmelerin hizmetlerini, yaptığı çalışmaları, referanslarını ve kurumsal kimliğini internet ortamında profesyonel biçimde sunabilmesi için hazırlanmıştır.\\r\\n\\r\\nNetvera Bobinajcı Sitesi Yazılımı standart kurumsal web sitesi şablonlarından farklı olarak doğrudan motor bobinaj ve elektrik motoru bakım-onarım sektörünün ihtiyaçlarına göre yapılandırılmıştır. AC/DC motor bobinaj, elektrik motoru sarımı, motor bakım ve onarım, arıza tespiti, pompa servisi, redüktör servisi, jeneratör bakımı, blower servisi ve yerinde teknik servis gibi ç