esi.\\\"\\r\\n  },\\r\\n  {\\r\\n    \\\"name\\\": \\\"NetVera Lisans Sistemi\\\",\\r\\n    \\\"description\\\": \\\"Merkezi lisans anahtarı ve yetkili domain doğrulaması.\\\"\\r\\n  },\\r\\n  {\\r\\n    \\\"name\\\": \\\"Otomatik Kurulum Sihirbazı\\\",\\r\\n    \\\"description\\\": \\\"cPanel ve paylaşımlı hostinglerde tarayıcı üzerinden çalışan adım adım kurulum sistemi.\\\"\\r\\n  }\\r\\n]\",\"specs_json\":\"[{\\\"label\\\":\\\"PHP\\\",\\\"value\\\":\\\"PHP 8.2, 8.3, 8.4 ve 8.5\\\"},{\\\"label\\\":\\\"Veritabanı\\\",\\\"value\\\":\\\"MySQL 8+ / MariaDB / PDO\\\"},{\\\"label\\\":\\\"Web Sunucusu\\\",\\\"value\\\":\\\"Apache veya LiteSpeed, .htaccess / mod_rewrite desteği\\\"},{\\\"label\\\":\\\"Tarayıcı\\\",\\\"value\\\":\\\"Google Chrome, Microsoft Edge, Mozilla Firefox, Safari ve güncel mobil tarayıcılar\\\"},{\\\"label\\\":\\\"Diğer Gereksinimler\\\",\\\"value\\\":\\\"PDO MySQL, mbstring, OpenSSL, cURL, fileinfo, JSON, session, filter, hash, DOM/libxml, Apache/LiteSpeed rewrite desteği ve yazılabilir .env/storage izinleri gereklidir. Üretim ortamında Composer veya Node.js zorunlu değildir. Lisans doğrulaması için hosting sunucusunun HTTPS üzerinden lisans.netvera.tr adresine erişebilmesi gerekir.\\\"},{\\\"label\\\":\\\"İşletim Sistemi\\\",\\\"value\\\":\\\"Linux / cPanel / Paylaşımlı Hosting\\\"},\\\"PHP 8.2, 8.3, 8.4 ve 8.5 uyumluluğu\\\",\\\"MySQL ve MariaDB desteği\\\",\\\"PDO prepared statements\\\",\\\"Framework zorunluluğu bulunmayan hafif MVC mimarisi\\\",\\\"Responsive ve mobil uyumlu tasarım\\\",\\\"Apache ve LiteSpeed desteği\\\",\\\"cPanel ve paylaşımlı hosting uyumluluğu\\\",\\\"Üretim ortamında Composer zorunluluğu yok\\\",\\\"Üretim ortamında Node.js zorunluluğu yok\\\",\\\"CSRF koruması\\\",\\\"Güvenli session yönetimi\\\",\\\"Login rate limit sistemi\\\",\\\"Form rate limit sistemi\\\",\\\"Güvenli medya yükleme kontrolleri\\\",\\\"JPG, JPEG, PNG, WEBP ve AVIF görsel desteği\\\",\\\"SVG dosya yükleme engeli\\\",\\\"Teklif eklerinin public webroo