/*!40000 ALTER TABLE `packages` ENABLE KEYS */;
DROP TABLE IF EXISTS `pages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pages` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `seo_title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_focus_keyword` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_score` int DEFAULT '0',
  `canonical_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `og_title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `og_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `og_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_slug` (`slug`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `pages` DISABLE KEYS */;
INSERT INTO `pages` VALUES (1,'Hakkımızda','hakkimizda','<h2>Hakkımızda</h2><p>Yorum Hizmeti olarak, dijital dünyada işletmelerin büyümesine yardımcı olan profesyonel hizmetler sunuyoruz. Google, sosyal medya, SEO ve dijital reklam alanlarında uzman ekibimizle müşterilerimize güvenilir ve etkili çözümler üretiyoruz.</p><h3>Misyonumuz</h3><p>İşletmelerin dijital varlığını güçlendirmek ve sürdürülebilir büyüme sağlamak için kaliteli, şeffaf ve güvenilir hizmet sunmaktır.</p><h3>Vizyonumuz</h3><p>Türkiye\'nin en güvenilir dijital hizmet platformu olmak.</p>','active','Hakkımızda - Yorum Hizmeti','Yorum Hizmeti hakkında bilgi edinin. Dijital hizmetlerde güvenilir çözüm ortağınız.',NULL,0,NULL,NULL,NULL,NULL,'2026-06-30 23:57:17','2026-06-30 23:57:17'),(2,'Gizlilik Politikası','gizlilik-politikasi','<h2>Gizlilik Politikası</h2><p>Bu gizlilik politikası, yorumhizmeti.tr web sitesinin kullanıcı verilerini nasıl topladığını, kullandığını ve koruduğunu açıklamaktadır.</p><p>Kişisel verileriniz 6698 sayılı KVKK kapsamında korunmaktadır.</p>','active','Gizlilik Politikası - Yorum Hizmeti','Yorum Hizmeti gizlilik politikası ve veri koruma bilgileri.',NULL,0,NULL,NULL,NULL,NULL,'2026-06-30 23:57:17','2026-06-30 23:57:17'),(3,'Mesafeli Satış Sözleşmesi','mesafeli-satis-sozlesmesi','<h2>Mesafeli Satış Sözleşmesi</h2><p>Bu sözleşme, 6502 sayılı Tüketicinin Korunması Hakkında Kanun ve Mesafeli Sözleşmeler Yönetmeliği kapsamında düzenlenmiştir.</p>','active','Mesafeli Satış Sözleşmesi - Yorum Hizmeti','Yorum Hizmeti mesafeli satış sözleşmesi.',NULL,0,NULL,NULL,NULL,NULL,'2026-06-30 23:57:17','2026-06-30 23:57:17'),(4,'KVKK Aydınlatma Metni','kvkk','<h2>KVKK Aydınlatma Metni</h2><p>6698 sayılı Kişisel Verilerin Korunması Kanunu kapsamında, kişisel verilerinizin işlenmesine ilişkin aydınlatma metnidir.</p>','active','KVKK Aydınlatma Metni - Yorum Hizmeti','KVKK kapsamında kişisel verilerin korunması hakkında bilgilendirme.',NULL,0,NULL,NULL,NULL,NULL,'2026-06-30 23:57:17','2026-06-30 23:57:17'),(5,'İade ve Teslimat Politikası','iade-teslimat-politikasi','<h2>İade ve Teslimat Politikası</h2><p>Hizmet başlamadan önce tam iade yapılmaktadır. Hizmet başladıktan sonra iade koşulları değerlendirilir.</p><h3>Teslimat</h3><p>Dijital hizmetlerimiz, sipariş onayından sonra belirtilen süre içinde teslim edilmektedir.</p>','active','İade ve Teslimat Politikası - Yorum Hizmeti','Yorum Hizmeti iade ve teslimat politikası.',NULL,0,NULL,NULL,NULL,NULL,'2026-06-30 23:57:17','2026-06-30 23:57:17');
